import numpy as np

def kmeans(X, k, iters=100):
    C = X[np.random.choice(len(X), k, replace=False)]
    for _ in range(iters):
        labels = np.argmin(((X[:, None] - C) ** 2).sum(2), axis=1)
        new_C = np.array([X[labels == j].mean(0) for j in range(k)])
        if np.allclose(new_C, C):
            break
        C = new_C
    return labels, C

