function kmeans(points, k, iters = 100) {
  let C = points.slice().sort(() => Math.random() - 0.5).slice(0, k);
  let labels;
  for (let t = 0; t < iters; t++) {
    labels = points.map(p =>
      C.reduce((b, c, i) => {
        const d = (p[0]-c[0])**2 + (p[1]-c[1])**2;
        return d < b.d ? { i, d } : b;
      }, { i: 0, d: Infinity }).i);
    const nc = C.map((_, i) => {
      const cl = points.filter((_, j) => labels[j] === i);
      if (!cl.length) return C[i];
      return [cl.reduce((s,p)=>s+p[0],0)/cl.length, cl.reduce((s,p)=>s+p[1],0)/cl.length];
    });
    if (JSON.stringify(nc) === JSON.stringify(C)) break;
    C = nc;
  }
  return { labels, centroids: C };
}
